update public.pages set content = '{"hero_heading": "Diversified investments. Integrated industries. Sustainable growth.", "hero_subheading": "Established in 1956, VECTIS is a Nigerian business group that connects capital, capability and opportunity across productive sectors, infrastructure and long-term value creation.", "intro_heading": "Built to connect capital, capability and opportunity", "intro_text": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "VECTIS brings investment management, enterprise development, operating platforms and strategic partnerships into one integrated architecture."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The portfolio is designed as an integrated system, not a flat list of businesses. Five connected clusters work together across the value chain: from capital and assets to operations, markets and community impact."}]}]}, "highlights": [{"heading": "Investment and financial services", "text": "Investment platforms provide the group''s strategic spine: capital allocation, financing solutions, shareholdings and portfolio governance."}, {"heading": "Energy and natural resources", "text": "Oil and gas, gas infrastructure, power generation, petroleum, and mining and minerals, including tin exploration and processing."}, {"heading": "Industry and productive enterprises", "text": "Manufacturing, processing, materials and productive enterprise development."}, {"heading": "Infrastructure and commercial services", "text": "Properties, construction, facility management, retail, telecommunications, information technology and media."}, {"heading": "Partnerships and social impact", "text": "Strategic alliances with serious partners, and community impact through the VECTIS Foundation."}], "cta_heading": "Built for serious partnerships", "cta_text": "VECTIS works with government institutions, domestic and international investors, development finance institutions, commercial banks, energy and industrial operators, technology providers, and joint-venture partners."}'::jsonb,
  seo_title = coalesce(seo_title, 'VECTIS · Established 1956 · A Nigerian business group'),
  seo_description = coalesce(seo_description, 'Diversified investments, integrated industries and sustainable growth. A Nigerian business group, established in 1956.'),
  status = 'published'
where page_key = 'home' and is_system and content = '{}'::jsonb;
update public.pages set content = '{"intro": "VECTIS is a diversified Nigerian business group, established in 1956. It brings investment management, enterprise development, operating platforms and strategic partnerships into one integrated architecture.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "One group, five connected business clusters"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The portfolio is designed as an integrated system, not a flat list of businesses. VECTIS is organised into five connected clusters:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Investment and financial services", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": the investment platforms that provide the group''s strategic spine."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Energy and natural resources", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": oil, gas, power, petroleum, mining and minerals."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Industry and productive enterprises", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": manufacturing, processing, materials and enterprise development."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Infrastructure and commercial services", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": places and access, digital reach and human capability."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Partnerships and social impact", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": strategic alliances and the VECTIS Foundation."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Investing across the value chain"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "From opportunity identification and financing to operations, infrastructure, distribution and community outcomes, VECTIS is designed to connect capabilities across sectors. Its model runs from "}, {"type": "text", "text": "capital", "marks": [{"type": "bold"}]}, {"type": "text", "text": " to "}, {"type": "text", "text": "assets", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "operations", "marks": [{"type": "bold"}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "markets", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", and on to lasting "}, {"type": "text", "text": "impact", "marks": [{"type": "bold"}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Turning assets into enterprises"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Industry, infrastructure and commercial services turn assets into enterprises:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Places and access", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": properties, construction, facility management and retail."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Industrial platforms", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": manufacturing, processing, materials and productive enterprise development."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Digital reach", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": telecommunications, information technology, media and communications."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Human capability", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": healthcare, pharmaceuticals, education and services."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Built for serious partnerships"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "VECTIS engages a broad range of counterparties across its investment platforms and operating clusters: government institutions, domestic and international investors, development finance institutions, commercial banks, energy and industrial operators, technology providers, and strategic joint-venture and project-development partners."}]}]}, "values": [{"heading": "Long-term value creation", "text": "We focus on productive sectors and infrastructure, building value that lasts."}, {"heading": "Integration", "text": "We connect capital, capability and opportunity across the value chain, rather than running a flat list of businesses."}, {"heading": "Discipline", "text": "We apply commercial discipline and robust oversight to every investment decision."}, {"heading": "Partnership", "text": "We build strategic alliances that give access to capabilities and markets."}, {"heading": "Community impact", "text": "Through the VECTIS Foundation, we extend enterprise into lasting community benefit."}]}'::jsonb,
