update public.pages set content = '{"intro": "The VECTIS portfolio is designed as an integrated system, not a flat list of businesses. Investment platforms provide the group''s strategic spine, and operating businesses carry its work into energy, natural resources, industry and beyond.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Investment platforms"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Global Investment, Capital, Holdings, Integrated Resources and & Partners together provide strategic investment, capital allocation, financing, portfolio governance, enterprise development and partnership and project development."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Energy and natural resources"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Oil and Gas, Gas & Power, Petroleum and Tin Mines span upstream resources, infrastructure, processing, trading and downstream markets."}]}]}}'::jsonb,
  seo_title = coalesce(seo_title, 'Our Businesses · VECTIS'),
  seo_description = coalesce(seo_description, 'The VECTIS businesses: investment platforms, energy and natural resources, and enterprises across fifteen sectors.'),
  status = 'published'
where page_key = 'businesses' and is_system and content = '{}'::jsonb;
update public.pages set content = '{"intro": "Fifteen sectors, one disciplined investment mandate. VECTIS applies an integrated lens across productive sectors, financial services, infrastructure, enterprise development and social development.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Investment platforms provide the strategic spine"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vectis Global Investment", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": strategic investments, capital allocation, portfolio oversight and business development."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "VECTIS Capital", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": investment structuring, financing solutions and capital mobilisation."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "VECTIS Holdings", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": shareholdings, strategic assets and portfolio governance."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vectis Integrated Resources", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": integrated investment and enterprise development."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vectis & Partners", "marks": [{"type": "bold"}]}, {"type": "text", "text": ": partnership and project development."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The sector mandate"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The portfolio spans essential systems and the capabilities that make them work: oil and gas; agriculture and agribusiness; telecommunications; banking and financial services; insurance; information technology; cement and building materials; media and communications; real estate, construction, facility management and retail; healthcare, pharmaceuticals and services; mining and quarrying; education and vocational training; sports and recreation; investments; and foundation and social development."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Each principle below links portfolio breadth to disciplined execution and long-term value creation."}]}]}, "principles": [{"heading": "Diversification", "text": "Spread capital across strategic sectors to reduce risk."}, {"heading": "Value chain", "text": "Develop integrated assets that enhance portfolio synergies."}, {"heading": "Partnerships", "text": "Forge strategic alliances to access capabilities and markets."}, {"heading": "Governance", "text": "Apply commercial discipline through robust oversight."}]}'::jsonb,
  seo_title = coalesce(seo_title, 'Investment Philosophy · VECTIS'),
  seo_description = coalesce(seo_description, 'Fifteen sectors, one disciplined investment mandate. Four principles guide how VECTIS deploys capital.'),
  status = 'published'
where page_key = 'investment-philosophy' and is_system and content = '{}'::jsonb;
update public.pages set content = '{"intro": "Governance turns ambition into accountable execution. At VECTIS, an accountability loop connects investment decisions to operating performance.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The governance framework"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Group Board and Executive Management"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Investment and Risk Committee"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Finance and Treasury"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Legal and Regulatory Compliance"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Audit and Internal Controls"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Environmental and Social Governance"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The accountability loop"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Decisions move through a continuous loop: from the "}, {"type": "text", "text": "Board and Executive", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", through "}, {"type": "text", "text": "Investment and Risk", "marks": [{"type": "bold"}]}, {"type": "text", "text": " review and "}, {"type": "text", "text": "Finance and Treasury", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", to "}, {"type": "text", "text": "Compliance and Audit", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", and back to the Board, so that every investment is followed through to its results."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Governance is also one of the four principles that guide how VECTIS deploys capital: applying commercial discipline through robust oversight."}]}]}}'::jsonb,
  seo_title = coalesce(seo_title, 'Governance · VECTIS'),
